t.script:
(function () {
    const WRAP_SELECTOR = '.o_product_indicator_wrap';

    const EASE = (t) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

    function smoothScrollTo(el, target, duration = 320) {
        const start = el.scrollLeft;
        const dist = target - start;
        if (!dist || duration <= 0) {
            el.scrollLeft = target;
            return;
        }
        let t0;
        const step = (ts) => {
            if (!t0) {
                t0 = ts;
            }
            const p = Math.min(1, (ts - t0) / duration);
            el.scrollLeft = start + dist * EASE(p);
            if (p < 1) {
                requestAnimationFrame(step);
            }
        };
        requestAnimationFrame(step);
    }

    function kineticScroll(el, velocity) {
        const max = Math.max(0, el.scrollWidth - el.clientWidth);
        let prev = performance.now();
        let v = velocity;
        const minV = 0.02;
        const friction = 0.94;

        function step(ts) {
            const dt = ts - prev;
            prev = ts;
            const decay = Math.pow(friction, dt / 16);
            v *= decay;
            if (Math.abs(v) < minV) {
                return;
            }

            let next = el.scrollLeft + v * dt;
            if (next < 0) {
                next = 0;
                v = 0;
            }
            if (next > max) {
                next = max;
                v = 0;
            }

            el.scrollLeft = next;
            if (v !== 0) {
                requestAnimationFrame(step);
            }
        }

        requestAnimationFrame(step);
    }

    function measureItem(track) {
        const first = track.querySelector('.o_product_indicator_item');
        if (!first) {
            return 0;
        }
        const rect = first.getBoundingClientRect();
        const styles = window.getComputedStyle(first);
        return rect.width + parseFloat(styles.marginLeft || 0) + parseFloat(styles.marginRight || 0);
    }

    function initWrap(wrap) {
        if (wrap.dataset.sliderInit) {
            return;
        }
        wrap.dataset.sliderInit = '1';

        const slider = wrap.querySelector('.o_product_indicator_slider');
        const track = wrap.querySelector('.o_product_indicator_track');
        const prevBtn = wrap.querySelector('.o_product_indicator_arrow--prev');
        const nextBtn = wrap.querySelector('.o_product_indicator_arrow--next');

        if (!slider || !track) {
            return;
        }

        const updateArrows = () => {
            const max = Math.max(0, slider.scrollWidth - slider.clientWidth);
            const hasOverflow = slider.scrollWidth > slider.clientWidth + 4;
            const atStart = slider.scrollLeft <= 1;
            const atEnd = slider.scrollLeft >= (max - 1);

            if (prevBtn) {
                prevBtn.hidden = !hasOverflow || atStart;
                prevBtn.disabled = atStart;
            }
            if (nextBtn) {
                nextBtn.hidden = !hasOverflow || atEnd;
                nextBtn.disabled = atEnd;
            }
        };

        const PAGE = () => {
            const itemSize = measureItem(track) || slider.clientWidth / 3;
            return itemSize * 3;
        };

        prevBtn && prevBtn.addEventListener('click', () => {
            smoothScrollTo(slider, Math.max(0, slider.scrollLeft - PAGE()), 320);
        });

        nextBtn && nextBtn.addEventListener('click', () => {
            const max = slider.scrollWidth - slider.clientWidth;
            smoothScrollTo(slider, Math.min(max, slider.scrollLeft + PAGE()), 320);
        });

        let isDown = false;
        let startX = 0;
        let startScroll = 0;
        let moved = false;
        let lastX = 0;
        let lastT = 0;
        let vx = 0;

        const start = (clientX) => {
            isDown = true;
            moved = false;
            vx = 0;
            slider.classList.add('is-dragging');
            const rect = slider.getBoundingClientRect();
            startX = clientX - rect.left;
            startScroll = slider.scrollLeft;
            lastX = clientX;
            lastT = performance.now();
        };

        const move = (clientX) => {
            if (!isDown) {
                return;
            }
            const rect = slider.getBoundingClientRect();
            const x = clientX - rect.left;
            const walk = x - startX;
            if (Math.abs(walk) > 3) {
                moved = true;
            }

            const now = performance.now();
            const dt = now - lastT || 1;
            vx = (clientX - lastX) / dt;
            lastX = clientX;
            lastT = now;

            slider.scrollLeft = startScroll - walk;
            updateArrows();
        };

        const end = () => {
            if (!isDown) {
                return;
            }
            isDown = false;
            slider.classList.remove('is-dragging');
            const vScroll = -vx;
            kineticScroll(slider, vScroll);
        };

        slider.addEventListener('mousedown', (ev) => {
            if (ev.button !== 0) {
                return;
            }
            start(ev.clientX);
            ev.preventDefault();
        });

        window.addEventListener('mousemove', (ev) => move(ev.clientX));
        window.addEventListener('mouseup', end);
        slider.addEventListener('mouseleave', end);

        slider.addEventListener('touchstart', (ev) => {
            const touch = ev.touches[0];
            if (!touch) {
                return;
            }
            start(touch.clientX);
        }, { passive: true });

        slider.addEventListener('touchmove', (ev) => {
            const touch = ev.touches[0];
            if (!touch) {
                return;
            }
            move(touch.clientX);
        }, { passive: true });

        slider.addEventListener('touchend', end);

        slider.addEventListener('click', (ev) => {
            if (moved) {
                ev.preventDefault();
                ev.stopPropagation();
            }
        }, true);

        slider.addEventListener('scroll', updateArrows, { passive: true });
        new ResizeObserver(updateArrows).observe(slider);
        updateArrows();
    }

    const initAll = () => {
        document.querySelectorAll(WRAP_SELECTOR).forEach(initWrap);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll, { once: true });
    } else {
        initAll();
    }

    document.addEventListener('product_variant_change', initAll);
})();
